// La Matriz de Riesgos real tiene 3 filas de encabezado fusionadas (categoria / campo / sub-campo),
// por lo que la fila 1 (usada por Spreadsheet File como header) queda casi vacia y las columnas llegan
// aqui como __EMPTY_1, __EMPTY_2, ... en vez de nombres legibles. Por eso el mapeo es POR POSICION de
// columna, no por nombre. Ademas el ID de riesgo NO se repite en las filas de continuacion de controles
// (a diferencia de Clientes/Contratos) -- hay que arrastrar el ultimo ID visto.

function col(row, key, altKey) {
  const v = row[key];
  if (v !== undefined && v !== null && v !== '') return v;
  if (altKey) return row[altKey];
  return undefined;
}

function parseDate(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') {
    const base = new Date(Date.UTC(1899, 11, 30));
    base.setUTCDate(base.getUTCDate() + v);
    return base.toISOString().slice(0, 10);
  }
  if (typeof v === 'string') {
    const trimmed = v.trim();
    if (/^\d+$/.test(trimmed)) {
      const base = new Date(Date.UTC(1899, 11, 30));
      base.setUTCDate(base.getUTCDate() + Number(trimmed));
      return base.toISOString().slice(0, 10);
    }
    const d = new Date(trimmed);
    if (!isNaN(d.getTime())) {
      const yyyy = d.getFullYear();
      const mm = String(d.getMonth() + 1).padStart(2, '0');
      const dd = String(d.getDate()).padStart(2, '0');
      return `${yyyy}-${mm}-${dd}`;
    }
  }
  return null;
}

function toNumber(v, fallback) {
  if (v === null || v === undefined || v === '') return fallback;
  const n = Number(String(v).replace(',', '.'));
  if (isNaN(n)) return fallback;
  return Math.round(n * 1000) / 1000;
}

function toText(v, fallback) {
  const s = String(v ?? '').trim();
  return s ? s : fallback;
}

function toBool(v) {
  const s = String(v || '').trim().toLowerCase();
  return s === 'si' || s === 'sí' || s === 'true' || s === '1' || s === 'x';
}

const rows = items.map((item) => item.json || {}).filter((row) => Object.keys(row).length > 0);
if (!rows.length) {
  throw new Error('No se encontraron filas en el Excel');
}

const riesgosMap = new Map();
let currentId = null;

for (const row of rows) {
  const rawId = String(row['__EMPTY_1'] || '').trim();
  const isNewRiskRow = /^R-/i.test(rawId);

  if (isNewRiskRow) {
    currentId = rawId;
    riesgosMap.set(currentId, {
      id: currentId,
      fechaIdentificacion: parseDate(row['__EMPTY_2']) || '-',
      fechaActualizacion: parseDate(row['__EMPTY_3']) || '-',
      procesoNivel1: toText(row['__EMPTY_4'], '-'),
      procesoNivel2: toText(row['__EMPTY_5'], 'N/A'),
      infoDocumentada: toText(row['__EMPTY_6'], '-'),
      duenoProceso: toText(row['__EMPTY_7'], '-'),
      duenoRiesgo: toText(col(row, 'MATRIZ DE RIESGOS OPERACIONALES', '__EMPTY_8b'), '-'),
      descripcion: toText(row['__EMPTY_8'], '-'),
      contexto: toText(row['__EMPTY_9'], '-'),
      parteInteresada: toText(row['__EMPTY_12'], '-'),
      causaQue: toText(row['__EMPTY_13'], '-'),
      causaPorQue: toText(row['__EMPTY_14'], '-'),
      causaQuien: toText(row['__EMPTY_15'], '-'),
      consecuencia: toText(row['__EMPTY_16'], '-'),
      impacto: {
        tipo: toText(row['__EMPTY_17'], '-'),
        calificacion: toText(row['__EMPTY_18'], '-'),
        valor: toNumber(row['__EMPTY_19'], 0)
      },
      probabilidad: {
        calificacion: toText(row['__EMPTY_20'], '-'),
        valor: toNumber(row['__EMPTY_21'], 0)
      },
      nivelInherente: {
        valor: toNumber(row['__EMPTY_22'], 0),
        severidad: toText(row['__EMPTY_23'], '-')
      },
      porcentajeMitigacion: toNumber(row['__EMPTY_42'], 0),
      nivelResidual: {
        severidad: toText(row['__EMPTY_43'], '-'),
        valor: toNumber(row['__EMPTY_44'], 0)
      },
      evidencia: toText(row['__EMPTY_41'], '-'),
      controles: []
    });
  }

  if (!currentId) continue; // filas antes del primer ID real (encabezados, ejemplos) -- se ignoran

  const controlDescripcion = toText(row['__EMPTY_24'], '');
  if (controlDescripcion) {
    riesgosMap.get(currentId).controles.push({
      descripcion: controlDescripcion,
      responsable: toText(row['__EMPTY_25'], '-'),
      tipo: toText(row['__EMPTY_26'], '-'),
      ejecucion: toText(row['__EMPTY_28'], '-'),
      origen: toText(row['__EMPTY_30'], '-'),
      documentado: toBool(row['__EMPTY_32']),
      nombreDocumento: toText(row['__EMPTY_34'], 'N/A'),
      frecuencia: toText(row['__EMPTY_35'], '-'),
      efectividad: toNumber(row['__EMPTY_37'], 0)
    });
  }

  // Si el riesgo aun no tiene evidencia y esta fila trae una, la tomamos (columna 41 es por-control).
  const riesgo = riesgosMap.get(currentId);
  if (riesgo.evidencia === '-') {
    const ev = toText(row['__EMPTY_41'], '');
    if (ev) riesgo.evidencia = ev;
  }
}

const riesgos = Array.from(riesgosMap.values());
return [{ json: { riesgos } }];
